class Solution:
 def maximumValue(self, strs):
  return max(int(s) if s.isdigit() else len(s) for s in strs)

class Solution:
 def deleteGreatestValue(self, grid):
  for row in grid: row.sort()
  return sum(max(row[j] for row in grid) for j in range(len(grid[0])))

class Solution:
 def similarPairs(self, words):
  sets=[frozenset(w) for w in words]
  return sum(1 for i in range(len(sets)) for j in range(i+1,len(sets)) if sets[i]==sets[j])

class Solution:
 def captureForts(self, forts):
  best=0; prev=None; prev_i=-1
  for i,x in enumerate(forts):
   if x:
    if prev is not None and x==-prev: best=max(best,i-prev_i-1)
    prev=x; prev_i=i
  return best

class Solution:
 def countDigits(self, num):
  return sum(1 for c in str(num) if num%int(c)==0)

class Solution:
 def maximumCount(self, nums):
  neg=sum(x<0 for x in nums); pos=sum(x>0 for x in nums)
  return max(neg,pos)

class Solution:
 def differenceOfSum(self, nums):
  element=sum(nums); digits=sum(int(c) for x in nums for c in str(x))
  return abs(element-digits)

class Solution:
 def getCommon(self, nums1, nums2):
  i=j=0
  while i<len(nums1) and j<len(nums2):
   if nums1[i]==nums2[j]: return nums1[i]
   if nums1[i]<nums2[j]: i+=1
   else: j+=1
  return -1

class Solution:
 def alternateDigitSum(self, n):
  total=0
  for i,c in enumerate(str(n)): total += int(c) if i%2==0 else -int(c)
  return total

class Solution:
 def separateDigits(self, nums):
  return [int(c) for x in nums for c in str(x)]
